#!/usr/bin/env node
// @ts-check
/**
 * Test-bed worker build (e2e bed L, `NOX_WORKER_BUILD_CMD`): a bundle whose
 * pinned snapshot is the local mesh's NoxRegistry, generated by the release
 * tooling itself.
 *
 *   1. read the bed's testbed.json: the upstream anvil RPC and the NoxRegistry
 *      the mesh nodes observe (address, deployment block, last registration);
 *   2. write a one-entry networks file for that registry (powDifficulty 0, the
 *      mesh's minimum) and capability hints from the liveness section of one
 *      node's served topology, as the release hints come from the seed;
 *   3. `make-snapshot.mjs` at the registration block (anvil has no finalized
 *      history, so --allow-unsafe-block), which reads the chain, cross-checks
 *      the fingerprint and runs the SDK's on-chain verification;
 *   4. `build.mjs --snapshot <that file> --outfile <out>`.
 *
 * The snapshot, networks and capability files land next to the bundle, so a
 * run keeps every input of the bundle it tested. Never used for a release:
 * the release snapshot is snapshot/nox-snapshot.json from the live registry.
 *
 * Usage: node scripts/build-test-worker.mjs --testbed <testbed.json> --out <bundle.js>
 */
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { parseArgs } from "node:util";
import { main as buildMain } from "./build.mjs";
import { isMain, runMain } from "./lib/cli.mjs";
import { main as snapshotMain } from "./make-snapshot.mjs";

export const TEST_NETWORK = "local-testbed";
/** Deadline for reading one node's served topology. */
const TOPOLOGY_TIMEOUT_MS = 5_000;

export class TestWorkerError extends Error {
  /**
   * @param {string} message
   * @param {"usage" | "testbed" | "topology" | "snapshot" | "build"} code
   */
  constructor(message, code) {
    super(message);
    this.name = "TestWorkerError";
    this.code = code;
  }
}

/**
 * @typedef {object} TestbedRegistry
 * @property {string} address
 * @property {number} chainId
 * @property {string} rpcUrl
 * @property {number} deployBlock
 * @property {number} registeredBlock
 */

/**
 * The registry and topology URLs a testbed.json describes.
 * @param {unknown} info
 * @returns {{ registry: TestbedRegistry, topologyUrls: string[] }}
 */
export function testbedRegistry(info) {
  const mesh = /** @type {{ mesh?: { registry?: Partial<TestbedRegistry>, nodes?: { topologyUrl?: unknown }[] } }} */ (info).mesh;
  const registry = mesh?.registry;
  if (
    registry === undefined ||
    typeof registry.address !== "string" ||
    !/^0x[0-9a-f]{40}$/u.test(registry.address) ||
    !Number.isSafeInteger(registry.chainId) ||
    typeof registry.rpcUrl !== "string" ||
    !Number.isSafeInteger(registry.deployBlock) ||
    !Number.isSafeInteger(registry.registeredBlock)
  ) {
    throw new TestWorkerError("testbed.json has no mesh.registry {address, chainId, rpcUrl, deployBlock, registeredBlock}", "testbed");
  }
  const topologyUrls = (mesh?.nodes ?? []).map((node) => node.topologyUrl).filter((url) => typeof url === "string");
  if (topologyUrls.length === 0) throw new TestWorkerError("testbed.json lists no mesh node topology URLs", "testbed");
  return { registry: /** @type {TestbedRegistry} */ (registry), topologyUrls: /** @type {string[]} */ (topologyUrls) };
}

/**
 * Capability hints from a served topology's liveness section, in the
 * `nox-capabilities/1` shape make-snapshot reads.
 * @param {unknown} topology
 * @param {string} source
 */
export function capabilitiesFromTopology(topology, source) {
  const liveness = /** @type {{ liveness?: { address?: unknown, capabilities?: unknown }[] }} */ (topology).liveness ?? [];
  /** @type {Record<string, string[]>} */
  const members = {};
  for (const entry of liveness) {
    if (typeof entry.address !== "string" || !Array.isArray(entry.capabilities)) continue;
    const hints = entry.capabilities.filter((hint) => typeof hint === "string");
    members[entry.address.toLowerCase()] = [...new Set(hints)].sort();
  }
  return { format: "nox-capabilities/1", source, members };
}

/**
 * @param {string[]} argv
 * @returns {Promise<number>}
 */
export async function main(argv) {
  const { values } = parseArgs({
    args: argv,
    options: {
      testbed: { type: "string" },
      out: { type: "string" },
      help: { type: "boolean", short: "h", default: false },
    },
  });
  if (values.help) {
    process.stdout.write("usage: build-test-worker.mjs --testbed <testbed.json> --out <bundle.js>\n");
    return 0;
  }
  if (values.testbed === undefined || values.out === undefined) {
    throw new TestWorkerError("--testbed and --out are required", "usage");
  }
  const out = resolve(values.out);
  const dir = dirname(out);
  mkdirSync(dir, { recursive: true });
  const { registry, topologyUrls } = testbedRegistry(JSON.parse(readFileSync(resolve(values.testbed), "utf8")));

  const networksPath = join(dir, "networks.json");
  writeFileSync(
    networksPath,
    `${JSON.stringify(
      {
        [TEST_NETWORK]: {
          chain_id: registry.chainId,
          registry: registry.address,
          from_block: registry.deployBlock,
          pow_difficulty: 0,
          source: "e2e bed L: NoxRegistry deployed on the local upstream anvil; nox_mesh_server nodes run with min_pow_difficulty 0.",
        },
      },
      null,
      2,
    )}\n`,
  );

  const topologyUrl = /** @type {string} */ (topologyUrls[0]);
  let topology;
  try {
    const response = await fetch(topologyUrl, { signal: AbortSignal.timeout(TOPOLOGY_TIMEOUT_MS) });
    topology = await response.json();
  } catch (error) {
    throw new TestWorkerError(`cannot read ${topologyUrl}: ${error instanceof Error ? error.message : String(error)}`, "topology");
  }
  const capabilitiesPath = join(dir, "capabilities.json");
  writeFileSync(
    capabilitiesPath,
    `${JSON.stringify(capabilitiesFromTopology(topology, `liveness section of ${topologyUrl} (local mesh node)`), null, 2)}\n`,
  );

  const snapshotPath = join(dir, "nox-snapshot.json");
  const snapshotCode = await snapshotMain([
    "--rpc", registry.rpcUrl,
    "--network", TEST_NETWORK,
    "--networks", networksPath,
    "--block", String(registry.registeredBlock),
    "--allow-unsafe-block",
    "--capabilities", capabilitiesPath,
    "--out", snapshotPath,
  ]);
  if (snapshotCode !== 0) throw new TestWorkerError(`make-snapshot exited with ${snapshotCode}`, "snapshot");
  const buildCode = await buildMain(["--snapshot", snapshotPath, "--outfile", out]);
  if (buildCode !== 0) throw new TestWorkerError(`build exited with ${buildCode}`, "build");
  return 0;
}

if (isMain(import.meta.url)) runMain("build-test-worker.mjs", main);
